import{_ as r,o,c as e,aj as a}from"./chunks/framework.DuzMo9U1.js";const c=JSON.parse('{"title":"嵌入式基础小知识","description":"记录日常遇到的嵌入式问题与参考答案","frontmatter":{"title":"嵌入式基础小知识","description":"记录日常遇到的嵌入式问题与参考答案","outline":"deep"},"headers":[],"relativePath":"pages/interview.md","filePath":"pages/interview.md"}'),n={name:"pages/interview.md"};function s(l,t,i,g,d,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="嵌入式基础小知识" tabindex="-1">嵌入式基础小知识 <a class="header-anchor" href="#嵌入式基础小知识" aria-label="Permalink to &quot;嵌入式基础小知识&quot;">​</a></h1><blockquote><p>记录日常遇到的问题和参考答案</p></blockquote><h2 id="嵌入式基础" tabindex="-1">嵌入式基础 <a class="header-anchor" href="#嵌入式基础" aria-label="Permalink to &quot;嵌入式基础&quot;">​</a></h2><h3 id="q1-什么是-volatile-什么时候用" tabindex="-1">Q1：什么是 volatile？什么时候用？ <a class="header-anchor" href="#q1-什么是-volatile-什么时候用" aria-label="Permalink to &quot;Q1：什么是 volatile？什么时候用？&quot;">​</a></h3><p><strong>答</strong>：volatile 告诉编译器该变量可能在程序控制之外被修改（如硬件寄存器、中断服务程序），每次访问都要从内存读取，不能做优化。</p><p><strong>典型场景</strong>：硬件寄存器、多线程共享变量、ISR 中修改的变量。</p><h3 id="q2-栈和堆的区别" tabindex="-1">Q2：栈和堆的区别？ <a class="header-anchor" href="#q2-栈和堆的区别" aria-label="Permalink to &quot;Q2：栈和堆的区别？&quot;">​</a></h3><p><strong>答</strong>：</p><ul><li>栈：函数局部变量、自动分配/释放、LIFO、空间小、速度快</li><li>堆：malloc 申请、手动 free、随机分配、空间大、速度慢</li></ul><h3 id="q3-待补充" tabindex="-1">Q3：（待补充） <a class="header-anchor" href="#q3-待补充" aria-label="Permalink to &quot;Q3：（待补充）&quot;">​</a></h3><hr><h2 id="rtos-相关-以-threadx-为主" tabindex="-1">RTOS 相关（以 ThreadX 为主） <a class="header-anchor" href="#rtos-相关-以-threadx-为主" aria-label="Permalink to &quot;RTOS 相关（以 ThreadX 为主）&quot;">​</a></h2><h3 id="q1-任务调度有哪些方式" tabindex="-1">Q1：任务调度有哪些方式？ <a class="header-anchor" href="#q1-任务调度有哪些方式" aria-label="Permalink to &quot;Q1：任务调度有哪些方式？&quot;">​</a></h3><p><strong>答</strong>：常见三类：</p><ul><li><strong>时间片轮转</strong>：同优先级线程轮流占用 CPU 一段时间。</li><li><strong>优先级抢占</strong>：高优先级就绪后立即打断低优先级正在运行的线程。</li><li><strong>协作式</strong>：低优先级主动 <code>yield</code>/阻塞才让出 CPU（现代 RTOS 多为抢占式为主）。</li></ul><p>ThreadX 属于 <strong>可抢占、基于优先级的调度</strong>；同优先级可用 <strong>时间片</strong>（若开启）轮转。</p><h3 id="q2-threadx-里线程、中断与「上下文」指什么" tabindex="-1">Q2：ThreadX 里线程、中断与「上下文」指什么？ <a class="header-anchor" href="#q2-threadx-里线程、中断与「上下文」指什么" aria-label="Permalink to &quot;Q2：ThreadX 里线程、中断与「上下文」指什么？&quot;">​</a></h3><ul><li><strong>线程（Thread）</strong>：有独立栈、优先级、入口函数；调度器在就绪线程里选最高优先级运行。</li><li><strong>中断（ISR）</strong>：硬件触发，在 <strong>中断栈/当前线程栈</strong>（与平台相关）上执行，<strong>不能阻塞</strong>（不能 <code>tx_thread_sleep</code>、不能拿会阻塞的同步原语）。</li><li><strong>上下文切换</strong>：保存当前线程的寄存器/栈指针等到 TCB，恢复下一个线程的寄存器/栈，切换发生在 <strong>调度点</strong>（阻塞、抢占、时间片耗尽、pend 等）。</li></ul><h3 id="q3-线程调度与线程切换一般在什么时机发生" tabindex="-1">Q3：线程调度与线程切换一般在什么时机发生？ <a class="header-anchor" href="#q3-线程调度与线程切换一般在什么时机发生" aria-label="Permalink to &quot;Q3：线程调度与线程切换一般在什么时机发生？&quot;">​</a></h3><p>典型触发点：</p><ul><li>线程调用 <strong>阻塞 API</strong>（如 <code>tx_semaphore_get</code> 带 timeout、<code>tx_queue_receive</code> 等）。</li><li><strong>更高优先级</strong>线程变为就绪（如 ISR 中 <code>tx_semaphore_put</code> 唤醒线程）。</li><li><strong>时间片</strong>用完（同优先级轮转）。</li><li>线程 <strong>主动让出</strong>（如 <code>tx_thread_relinquish</code>，视配置）。</li></ul><h3 id="q4-互斥量-mutex-、信号量、二值信号量、事件标志组各干什么" tabindex="-1">Q4：互斥量（Mutex）、信号量、二值信号量、事件标志组各干什么？ <a class="header-anchor" href="#q4-互斥量-mutex-、信号量、二值信号量、事件标志组各干什么" aria-label="Permalink to &quot;Q4：互斥量（Mutex）、信号量、二值信号量、事件标志组各干什么？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>典型用途</th><th>ThreadX 侧要点</th></tr></thead><tbody><tr><td><strong>互斥量 Mutex</strong></td><td>保护 <strong>临界区</strong>、互斥访问共享资源；支持 <strong>优先级继承</strong>（可缓解优先级反转）</td><td><code>tx_mutex_get/put</code>；持锁时间要短</td></tr><tr><td><strong>计数信号量 Semaphore</strong></td><td>资源计数、生产-消费「许可」</td><td><code>tx_semaphore_get/put</code></td></tr><tr><td><strong>二值信号量</strong></td><td>可看作计数最大为 1 的信号量；常用于 <strong>单次通知/同步</strong></td><td>同上，初始 count 设为 0/1</td></tr><tr><td><strong>事件标志组 Event Flags</strong></td><td>多条件组合唤醒：等 <strong>多个位</strong> 的 AND/OR</td><td><code>tx_event_flags_get/set</code></td></tr></tbody></table><p><strong>选用建议</strong>：只保护数据用 <strong>Mutex</strong>；发信号/计数用 <strong>Semaphore</strong>；多事件组合用 <strong>Event Flags</strong>。</p><h3 id="q5-队列-message-queue-在-rtos-里怎么用" tabindex="-1">Q5：队列（Message Queue）在 RTOS 里怎么用？ <a class="header-anchor" href="#q5-队列-message-queue-在-rtos-里怎么用" aria-label="Permalink to &quot;Q5：队列（Message Queue）在 RTOS 里怎么用？&quot;">​</a></h3><ul><li>线程间传递 <strong>定长消息</strong>（数据块拷贝进队列），发送方与接收方 <strong>解耦</strong>。</li><li>ThreadX：<code>tx_queue_create/send/front_send/receive</code>；注意 <strong>消息长度固定</strong>、队列深度要按峰值流量设计。</li><li>ISR 中通常用 <strong>非阻塞</strong> 或 <strong>专用 ISR 安全 API</strong>（视 port 文档），避免在 ISR 里长时间等待。</li></ul><h3 id="q6-字节池-byte-pool-与堆分配是什么关系" tabindex="-1">Q6：字节池（Byte Pool）与堆分配是什么关系？ <a class="header-anchor" href="#q6-字节池-byte-pool-与堆分配是什么关系" aria-label="Permalink to &quot;Q6：字节池（Byte Pool）与堆分配是什么关系？&quot;">​</a></h3><ul><li><strong>Byte Pool</strong>：ThreadX 提供的 <strong>可变长度</strong> 内存池，从池中 <code>allocate</code>/<code>release</code>，可减少碎片、行为比裸 <code>malloc</code> 更可预期（仍要注意碎片与并发）。</li><li><strong>堆（Heap）</strong>：常指 C 库 <code>malloc/free</code> 或启动文件划给 <code>_heap</code> 的区域；与 <strong>线程栈</strong>（静态或分配自 byte pool）是不同概念。</li><li><strong>实践</strong>：关键路径、ISR 附近避免频繁 <code>malloc</code>；大块、长期对象可静态或池化；用完必须 <strong>配对释放</strong>，避免泄漏。</li></ul><h3 id="q7-线程与中断切换过程、如何保护临界区" tabindex="-1">Q7：线程与中断切换过程、如何保护临界区？ <a class="header-anchor" href="#q7-线程与中断切换过程、如何保护临界区" aria-label="Permalink to &quot;Q7：线程与中断切换过程、如何保护临界区？&quot;">​</a></h3><p><strong>中断 → 线程</strong>：ISR 里可 <code>put</code> 信号量等唤醒线程；真正线程切换往往在 <strong>ISR 退出后</strong> 由调度器完成（与架构相关）。</p><p><strong>保护临界区的常用方式</strong>：</p><ol><li><strong>关中断</strong> <code>disable/enable</code>：最短路径保护 <strong>少量共享标志/指针</strong>；持锁时间必须极短。</li><li><strong>Mutex</strong>：线程级互斥，可配合优先级继承；<strong>不要在持锁时做耗时操作</strong>。</li><li><strong>只读数据</strong> 或 <strong>无锁队列</strong>（高级）：减少锁竞争。</li></ol><p><strong>注意</strong>：在 ISR 里不要长时间关中断；不要在中断里等 Mutex（易死锁）。</p><h3 id="q8-优先级反转是什么-mutex-如何缓解" tabindex="-1">Q8：优先级反转是什么？Mutex 如何缓解？ <a class="header-anchor" href="#q8-优先级反转是什么-mutex-如何缓解" aria-label="Permalink to &quot;Q8：优先级反转是什么？Mutex 如何缓解？&quot;">​</a></h3><ul><li><strong>现象</strong>：高优先级线程等低优先级占用的资源，而低优先级又被 <strong>中优先级</strong> 抢占，导致高优先级 <strong>长时间阻塞</strong>。</li><li><strong>缓解</strong>：<strong>优先级继承 Mutex</strong>（ThreadX Mutex 支持）：持锁线程临时提升到等待该锁的最高优先级线程的级别，释放后恢复。</li><li><strong>设计</strong>：缩短临界区、减少持锁范围、避免在持锁路径上调用可能阻塞的 API。</li></ul><hr><h2 id="pid-与调试" tabindex="-1">PID 与调试 <a class="header-anchor" href="#pid-与调试" aria-label="Permalink to &quot;PID 与调试&quot;">​</a></h2><h3 id="q1-位置式-pid-与增量式-pid" tabindex="-1">Q1：位置式 PID 与增量式 PID <a class="header-anchor" href="#q1-位置式-pid-与增量式-pid" aria-label="Permalink to &quot;Q1：位置式 PID 与增量式 PID&quot;">​</a></h3><p><strong>位置式</strong>（全量输出，离散形式示意）：</p><ul><li><code>u(k) = Kp*e(k) + Ki*Σe(i) + Kd*(e(k)-e(k-1))</code></li><li>直接给出 <strong>控制量</strong>（如 PWM 占空、DAC）。</li><li>积分项累积明显，参数整定直观；积分饱和（windup）需注意。</li></ul><p><strong>增量式</strong>（Δu）：</p><ul><li><code>Δu(k) = Kp*(e(k)-e(k-1)) + Ki*e(k) + Kd*(e(k)-2e(k-1)+e(k-2))</code>（常见写法之一，与教材离散化可能略有差异，以你实现为准）</li><li>输出为 <strong>增量</strong>，执行机构积分（如步进、阀位累加）时较自然；切换冲击小。</li></ul><h3 id="q2-如何减小或消除稳态误差" tabindex="-1">Q2：如何减小或消除稳态误差？ <a class="header-anchor" href="#q2-如何减小或消除稳态误差" aria-label="Permalink to &quot;Q2：如何减小或消除稳态误差？&quot;">​</a></h3><ul><li><strong>积分项 Ki</strong>：消除 <strong>常值扰动</strong> 带来的静差（I 作用把平均误差拉向 0）；Ki 过大易振荡、超调。</li><li><strong>前馈</strong>：已知扰动（如负载、重力）可补偿，减轻对 I 的依赖。</li><li><strong>死区与量化</strong>：传感器噪声大时，过小误差不要进积分（<strong>死区</strong>或<strong>积分分离</strong>），避免抖动。</li><li><strong>抗积分饱和</strong>：输出限幅时停止或对积分 <strong>clamp</strong>，避免 I 项「堆满」导致大超调。</li><li><strong>采样周期</strong>：过慢会等效延迟大，PID 难稳；与滤波截止频率匹配。</li></ul><h3 id="q3-调试顺序建议" tabindex="-1">Q3：调试顺序建议 <a class="header-anchor" href="#q3-调试顺序建议" aria-label="Permalink to &quot;Q3：调试顺序建议&quot;">​</a></h3><p>先 <strong>P</strong> 使系统有响应且不过振 → 加 <strong>I</strong> 压静差 → 必要时加 <strong>D</strong> 抑超调（对噪声敏感需先低通）。阶跃响应看 <strong>超调、调节时间、稳态误差</strong>；扫频或记录阶跃数据辅助。</p><hr><h2 id="卡尔曼滤波、最小二乘与快排-工程应用" tabindex="-1">卡尔曼滤波、最小二乘与快排（工程应用） <a class="header-anchor" href="#卡尔曼滤波、最小二乘与快排-工程应用" aria-label="Permalink to &quot;卡尔曼滤波、最小二乘与快排（工程应用）&quot;">​</a></h2><h3 id="q1-卡尔曼滤波-kalman-filter-在嵌入式里干什么用" tabindex="-1">Q1：卡尔曼滤波（Kalman Filter）在嵌入式里干什么用？ <a class="header-anchor" href="#q1-卡尔曼滤波-kalman-filter-在嵌入式里干什么用" aria-label="Permalink to &quot;Q1：卡尔曼滤波（Kalman Filter）在嵌入式里干什么用？&quot;">​</a></h3><p>在 <strong>有过程噪声</strong> 和 <strong>测量噪声</strong> 时，对状态（位置、速度、姿态、传感器融合）做 <strong>最优（线性高斯假设下）估计</strong>。</p><ul><li><strong>预测</strong>：用模型推下一时刻状态。</li><li><strong>更新</strong>：用新测量修正，增益 K 由噪声协方差自动权衡「信模型还是信传感器」。</li><li><strong>应用</strong>：IMU+编码器融合、温漂估计、电池 SOC 估计（扩展卡尔曼 EKF/无迹 UKF 用于非线性）。</li></ul><p><strong>实践</strong>：矩阵维数要小；定点或简化为 <strong>一阶低通+互补</strong> 若算力极紧。</p><h3 id="q2-最小二乘法拟合曲线" tabindex="-1">Q2：最小二乘法拟合曲线 <a class="header-anchor" href="#q2-最小二乘法拟合曲线" aria-label="Permalink to &quot;Q2：最小二乘法拟合曲线&quot;">​</a></h3><p>给定数据点 (xi, yi)，选模型（如直线 y=ax+b、多项式），使 <strong>残差平方和最小</strong>。</p><ul><li><strong>应用</strong>：传感器 <strong>标定曲线</strong>、温漂补偿、简易非线性校正。</li><li><strong>实现</strong>：正规方程或递推最小二乘（RLS）适合在线更新；注意病态矩阵时用 QR/SVD（资源够时）。</li></ul><h3 id="q3-快排-quicksort-处理数据的实际应用" tabindex="-1">Q3：快排（Quicksort）处理数据的实际应用 <a class="header-anchor" href="#q3-快排-quicksort-处理数据的实际应用" aria-label="Permalink to &quot;Q3：快排（Quicksort）处理数据的实际应用&quot;">​</a></h3><p>对 <strong>数组排序</strong> 平均时间复杂度 O(n log n)。</p><ul><li><strong>应用</strong>：取 <strong>中位数</strong> 抗野值、滑动窗口内排序后取分位、日志时间戳整理、ADC 批量采样后 <strong>剔除极值再平均</strong>。</li><li><strong>嵌入式注意</strong>：最坏情况递归深度；可改 <strong>堆排序</strong> 或 <strong>插入排序</strong>（小数组）保证栈与最坏时间；避免在中断里做大数组排序。</li></ul><hr><h2 id="stm32-定时器与「回调里能做什么」" tabindex="-1">STM32 定时器与「回调里能做什么」 <a class="header-anchor" href="#stm32-定时器与「回调里能做什么」" aria-label="Permalink to &quot;STM32 定时器与「回调里能做什么」&quot;">​</a></h2><h3 id="q1-定时器中断-回调的「上下文」是什么" tabindex="-1">Q1：定时器中断/回调的「上下文」是什么？ <a class="header-anchor" href="#q1-定时器中断-回调的「上下文」是什么" aria-label="Permalink to &quot;Q1：定时器中断/回调的「上下文」是什么？&quot;">​</a></h3><ul><li>定时器到点触发 <strong>中断</strong>，在 <strong>ISR 上下文</strong> 执行（优先级由 NVIC 配置）。</li><li>与 RTOS 线程不同：ISR 内 <strong>不能</strong> 使用会 <strong>阻塞</strong> 的 RTOS 调用；应只做 <strong>清标志、读计数、写 GPIO、发信号</strong> 等短操作。</li></ul><h3 id="q2-执行完为什么会「退出」-下次怎么再来" tabindex="-1">Q2：执行完为什么会「退出」？下次怎么再来？ <a class="header-anchor" href="#q2-执行完为什么会「退出」-下次怎么再来" aria-label="Permalink to &quot;Q2：执行完为什么会「退出」？下次怎么再来？&quot;">​</a></h3><ul><li>ISR <strong>执行完 <code>return</code></strong>，硬件清除或软件清除 <strong>更新/比较中断标志</strong> 后，CPU 回到被打断的线程。</li><li>定时器 <strong>自动重装</strong>（如 ARR 更新）则到点会 <strong>再次</strong> 进中断；若未使能下次中断或关闭了定时器，则不再进。</li></ul><h3 id="q3-定时器中断里会不会「优先级反转」" tabindex="-1">Q3：定时器中断里会不会「优先级反转」？ <a class="header-anchor" href="#q3-定时器中断里会不会「优先级反转」" aria-label="Permalink to &quot;Q3：定时器中断里会不会「优先级反转」？&quot;">​</a></h3><ul><li><strong>经典优先级反转</strong> 多指 <strong>RTOS 下 Mutex + 多线程</strong> 的场景。</li><li>若 ISR 里 <strong>抢 Mutex</strong> 而另一低优先级线程已持锁，可能拖长 ISR（<strong>极不推荐在 ISR 里拿 Mutex</strong>）。</li><li>NVIC 层面：高抢占优先级的中断可打断低优先级 ISR，这是 <strong>中断嵌套</strong>，不是 Mutex 反转，但要控制 <strong>ISR 长度</strong> 与 <strong>栈使用</strong>。</li></ul><h3 id="q4-为什么定时器回调里不能跑太久" tabindex="-1">Q4：为什么定时器回调里不能跑太久？ <a class="header-anchor" href="#q4-为什么定时器回调里不能跑太久" aria-label="Permalink to &quot;Q4：为什么定时器回调里不能跑太久？&quot;">​</a></h3><ul><li><strong>阻塞其他中断与线程</strong>：关闭或延迟同级/低优先级中断响应，抖动变大。</li><li><strong>RTOS 时钟节拍漂移</strong>：若 SysTick/调度依赖 tick，长时间关中断会破坏 <strong>实时性</strong>。</li><li><strong>栈与 WCET</strong>：ISR 嵌套消耗栈；过长增大 <strong>最坏执行时间</strong>，系统难以保证截止期。</li></ul><p><strong>建议</strong>：ISR 内只做 <strong>拷贝数据、置位、给信号量</strong>；重活放到 <strong>线程</strong> 里做。</p><hr><h2 id="项目相关" tabindex="-1">项目相关 <a class="header-anchor" href="#项目相关" aria-label="Permalink to &quot;项目相关&quot;">​</a></h2><p>（根据你的项目，提前准备好「项目难点」「如何解决」的话术）</p>',72)])])}const q=r(n,[["render",s]]);export{c as __pageData,q as default};
